import{_ as t,a0 as r,w as o,s as d,ao as p,I as l,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"通過“猜數字”遊戲學習 Basic | LCTT x X-CMD","titleTemplate":false,"description":"通過“猜數字”遊戲學習 Basic | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過“猜數字”遊戲學習 Basic | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過“猜數字”遊戲學習 Basic | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230202.1 ⭐️ Learn Basic by coding a game","title":"通過“猜數字”遊戲學習 Basic","tag":"202302","desc":""},"relativePath":"202302/20230202.1 ⭐️ Learn Basic by coding a game.md","filePath":"[post].md"}'),u={name:"202302/20230202.1 ⭐️ Learn Basic by coding a game.md"};function g(b,s,h,c,k,m){const n=r("Link");return o(),d("div",null,[s[23]||(s[23]=p('<h1 id="通過-猜數字-遊戲學習-basic" tabindex="-1">通過“猜數字”遊戲學習 Basic <a class="header-anchor" href="#通過-猜數字-遊戲學習-basic" aria-label="Permalink to “通過“猜數字”遊戲學習 Basic”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/11/103834qsra0ryedbdnrdez.jpg" alt=""></p><blockquote><p>本教程讓你通過編寫一個 “猜數字” 遊戲來探索 Basic。</p></blockquote><p>用多種語言編寫同一個應用是學習新的編程語言的好方法。大多數編程語言都有某些共同點，如：</p><ul><li>變量</li><li>表達式</li><li>語句</li></ul><p>這些概念是大多數編程語言的基礎。當你理解了它們，你就可以開始研究其他的東西了。</p><p>編程語言通常有一些相似之處。當你瞭解了一種編程語言，你就可以通過認識其差異來學習另一種語言的基礎知識。</p><p>用標準程序進行練習是學習新語言的一個好方法。它使你能夠專注於語言，而不是程序的邏輯。在這個系列文章中，我使用了一個“猜數字”的程序，在這個程序中，計算機在 1 到 100 之間挑選一個數字，並要求你猜出來。程序循環進行，直到你猜對數字為止。</p><p>這個程序鍛鍊了編程語言中的幾個概念：</p><ul><li>變量</li><li>輸入</li><li>輸出</li><li>條件判斷</li><li>循環</li></ul><p>這是學習一種新的編程語言的很好的實踐。本文主要介紹 Basic。</p><h3 id="在-bywater-basic-中猜數字" tabindex="-1">在（Bywater）Basic 中猜數字 <a class="header-anchor" href="#在-bywater-basic-中猜數字" aria-label="Permalink to “在（Bywater）Basic 中猜數字”">​</a></h3>',12)),l("p",null,[s[1]||(s[1]=a("對於 Basic 編程語言，沒有真正的標準。維基百科説：“BASIC（",-1)),s[2]||(s[2]=l("ruby",null,[a("初學者通用符號指令代碼"),l("rt",null,"Beginners' All-purpose Symbolic Instruction Code")],-1)),s[3]||(s[3]=a("）是一個通用的高級編程語言系列，旨在方便使用”。",-1)),i(n,{href:"https://yeolpishack.net/repos/ChipMaster/bwBASIC"},{default:e(()=>[...s[0]||(s[0]=[a("BWBasic",-1)])]),_:1}),s[4]||(s[4]=a(" 的實現是在 GPL 下提供的。",-1))]),s[24]||(s[24]=p(`<p>你可以通過編寫一個“猜數字”遊戲來探索 Basic。</p><h3 id="在-linux-上安裝-basic" tabindex="-1">在 Linux 上安裝 Basic <a class="header-anchor" href="#在-linux-上安裝-basic" aria-label="Permalink to “在 Linux 上安裝 Basic”">​</a></h3><p>在 Debian 或 Ubuntu 中，你可以用以下方法安裝 Basic：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ apt install -y bwbasic</span></span></code></pre></div><p>下載 Fedora、CentOS、Mageia 和其他任何 Linux 發行版的最新版本 tarball。解壓並設置可執行，然後從終端運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar --extract --file bwbasic*z</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ chmod +x bywater</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ./bywater</span></span></code></pre></div>`,6)),l("p",null,[s[6]||(s[6]=a("在 Windows 上，",-1)),i(n,{href:"https://github.com/nerun/bwbasic/releases"},{default:e(()=>[...s[5]||(s[5]=[a("下載 .exe 版本",-1)])]),_:1}),s[7]||(s[7]=a("。",-1))]),s[25]||(s[25]=p(`<h3 id="basic-代碼" tabindex="-1">Basic 代碼 <a class="header-anchor" href="#basic-代碼" aria-label="Permalink to “Basic 代碼”">​</a></h3><p>下面是我的實現：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>10 value$ = cint(rnd * 100) + 1</span></span>
<span class="line"><span>20 input &quot;enter guess&quot;; guess$</span></span>
<span class="line"><span>30 guess$ = val(guess$)</span></span>
<span class="line"><span>40 if guess$ &lt; value$ then print &quot;Too low&quot;</span></span>
<span class="line"><span>50 if guess$ &gt; value$ then print &quot;Too high&quot;</span></span>
<span class="line"><span>60 if guess$ = value$ then 80</span></span>
<span class="line"><span>70 goto 20</span></span>
<span class="line"><span>80 print &quot;That&#39;s right&quot;</span></span></code></pre></div><p>Basic 程序可以是編號的，也可以是不編號的。通常情況下，寫程序時最好不編號，但用編號的行來寫，可以更容易地引用各個行。</p><p>按照慣例，編碼者將行寫成 10 的倍數。這種方法允許在現有的行之間插入新的行，以便進行調試。下面是我對上述方法的解釋：</p><ul><li>10 行：使用內置的 <code>rnd</code> 函數計算一個 1 到 100 之間的隨機值，該函數生成一個 0 到 1 之間的數字，不包括 1。</li><li>20 行：詢問一個猜測，並將該值放入 <code>guess$</code> 標量變量。30 行將該值轉換為一個數字。</li><li>40 行和 50 行：根據比較結果，給猜測者以反饋。</li><li>70 行：回到循環的起點。</li><li>60 行：通過將控制權轉移到 80 行來打破循環。80 行是最後一行，所以程序在這之後退出。</li></ul><h3 id="輸出示例" tabindex="-1">輸出示例 <a class="header-anchor" href="#輸出示例" aria-label="Permalink to “輸出示例”">​</a></h3><p>下面是將該程序放入 <code>program.bas</code> 後的一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bwbasic program.bas</span></span>
<span class="line"><span>Bywater BASIC Interpreter/Shell, version 2.20 patch level 2</span></span>
<span class="line"><span>Copyright (c) 1993, Ted A. Campbell</span></span>
<span class="line"><span>Copyright (c) 1995-1997, Jon B. Volkoff</span></span>
<span class="line"><span></span></span>
<span class="line"><span>enter guess? 50</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 75</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 88</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>enter guess? 80</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 84</span></span>
<span class="line"><span>Too low</span></span>
<span class="line"><span>enter guess? 86</span></span>
<span class="line"><span>Too high</span></span>
<span class="line"><span>enter guess? 85</span></span>
<span class="line"><span>That&#39;s right</span></span></code></pre></div><h3 id="開始學習" tabindex="-1">開始學習 <a class="header-anchor" href="#開始學習" aria-label="Permalink to “開始學習”">​</a></h3><p>這個“猜數字”遊戲是學習新的編程語言的一個很好的入門程序，因為它以一種相當直接的方式鍛鍊了幾個常見的編程概念。通過在不同的編程語言中實現這個簡單的遊戲，你可以展示這些語言的一些核心概念，並比較它們的細節。</p><p>你有喜歡的編程語言嗎？你會如何用它來寫“猜數字”的遊戲？請關注本系列文章，看看你可能感興趣的其他編程語言的例子吧！</p><hr>`,13)),l("p",null,[s[9]||(s[9]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/23/2/learn-basic-coding-game"},{default:e(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/23/2/learn-basic-coding-game",-1)])]),_:1})]),l("p",null,[s[14]||(s[14]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[10]||(s[10]=[a("Moshe Zadka",-1)])]),_:1}),s[15]||(s[15]=a(" 選題：",-1)),i(n,{href:"https://github.com/lkxed"},{default:e(()=>[...s[11]||(s[11]=[a("lkxed",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[12]||(s[12]=[a("geekpi",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const B=t(u,[["render",g]]);export{C as __pageData,B as default};
